  platformFeeMaxCap: 200,
  // Max ₹200 platform fee
  // Convenience fee: flat fee for bookings
  convenienceFee: 10,
  // ₹10 flat
  // Delivery fee (for at_home services and orders)
  deliveryFee: 0,
  // Usually calculated by logistics
  // Packaging fee (for orders)
  packagingFee: 0,
