var AddFundsByPhoneHandler = class extends BaseHandler {
  async handle(context) {
    const body = this.parseBody(context.event);
    const { phone, amount, referenceType, referenceId, description, idempotencyKey } = body;
    const requestId = context.event.requestContext?.requestId;
    if (!phone) {
      return this.error("Phone number is required", 400);
    }
    if (!amount || typeof amount !== "number" || amount <= 0) {
      return this.error("Amount must be a positive number", 400);
    }
    const customerId = await getCustomerIdByPhone(phone);
    if (!customerId) {
      return this.error("Customer not found for the provided phone number", 404);
    }
    if (idempotencyKey) {
      const existing = await checkIdempotencyKey(idempotencyKey);
      if (existing.exists) {
        return this.success({
          ...existing.response,
          cached: true,
          message: "Transaction already processed"
        });
      }
    }
    const result = await withTransaction(async (client2) => {
      const walletResult = await client2.query(
        `SELECT id, customer_id, balance, currency
         FROM customer_wallets
         WHERE customer_id = $1
         FOR UPDATE`,
        [customerId]
      );
      let wallet;
      if (walletResult.rows.length === 0) {
        const createResult = await client2.query(
          `INSERT INTO customer_wallets (customer_id, balance, currency)
           VALUES ($1, $2, 'INR')
           RETURNING *`,
          [customerId, amount]
        );
        wallet = createResult.rows[0];
      } else {
        wallet = walletResult.rows[0];
        const updateResult = await client2.query(
          `UPDATE customer_wallets
           SET balance = balance + $1, updated_at = NOW()
           WHERE customer_id = $2
           RETURNING *`,
          [amount, customerId]
        );
        wallet = updateResult.rows[0];
      }
      const txnResult = await client2.query(
        `INSERT INTO wallet_transactions (
          customer_id, transaction_type, amount, balance_after,
          reference_type, reference_id, description
        ) VALUES ($1, $2, $3, $4, $5, $6, $7)
        RETURNING *`,
        [
          customerId,
          "credit",
          amount,
          wallet.balance,
          referenceType || "add_funds",
          referenceId || null,
          description || "Wallet top-up"
        ]
      );
      return {
        wallet,
        transaction: txnResult.rows[0]
      };
    });
    await logAuditEntry({
      entityType: "wallet",
      entityId: result.wallet.id,
      action: "add_funds",
      newValues: {
        amount,
        balanceAfter: result.wallet.balance,
        phone
      },
      actorId: customerId,
      actorType: "customer",
      requestId
    });
    const response = {
      success: true,
      transactionId: result.transaction.id,
      customerId,
      amount: Number(amount),
      newBalance: Number(result.wallet.balance),
      transactionType: "credit",
      timestamp: result.transaction.created_at,
      message: "Funds added successfully"
    };
    if (idempotencyKey) {
      await storeIdempotencyKey(
        idempotencyKey,
        "wallet_transaction",
        result.transaction.id,
        response,
        200
      );
    }
    return this.success(response);
  }
};
var UseWalletByPhoneHandler = class extends BaseHandler {
  async handle(context) {
    const body = this.parseBody(context.event);
    const { phone, amount, referenceType, referenceId, description, idempotencyKey } = body;
    const requestId = context.event.requestContext?.requestId;
    if (!phone) {
      return this.error("Phone number is required", 400);
    }
    if (!amount || typeof amount !== "number" || amount <= 0) {
      return this.error("Amount must be a positive number", 400);
    }
    const customerId = await getCustomerIdByPhone(phone);
    if (!customerId) {
      return this.error("Customer not found for the provided phone number", 404);
    }
    if (idempotencyKey) {
      const existing = await checkIdempotencyKey(idempotencyKey);
      if (existing.exists) {
        return this.success({
          ...existing.response,
          cached: true,
          message: "Transaction already processed"
        });
      }
    }
    try {
      const result = await withTransaction(async (client2) => {
        const walletResult = await client2.query(
          `SELECT id, customer_id, balance, currency
           FROM customer_wallets
           WHERE customer_id = $1
           FOR UPDATE`,
          [customerId]
        );
        if (walletResult.rows.length === 0) {
          throw new Error("Wallet not found");
        }
        const wallet = walletResult.rows[0];
        if (parseFloat(wallet.balance) < amount) {
          throw new Error("Insufficient balance");
        }
        const updateResult = await client2.query(
          `UPDATE customer_wallets
           SET balance = balance - $1, updated_at = NOW()
           WHERE customer_id = $2 AND balance >= $1
           RETURNING *`,
          [amount, customerId]
        );
        if (updateResult.rows.length === 0) {
          throw new Error("Insufficient balance (race condition)");
        }
        const updatedWallet = updateResult.rows[0];
        const txnResult = await client2.query(
          `INSERT INTO wallet_transactions (
            customer_id, transaction_type, amount, balance_after,
            reference_type, reference_id, description
          ) VALUES ($1, $2, $3, $4, $5, $6, $7)
          RETURNING *`,
          [
            customerId,
            "debit",
            amount,
            updatedWallet.balance,
            referenceType || "payment",
            referenceId || null,
            description || "Wallet payment"
          ]
        );
        return {
          wallet: updatedWallet,
          transaction: txnResult.rows[0]
        };
      });
      await logAuditEntry({
        entityType: "wallet",
        entityId: result.wallet.id,
        action: "use_wallet",
        newValues: {
          amount,
          balanceAfter: result.wallet.balance,
          phone,
          referenceType,
          referenceId
        },
        actorId: customerId,
        actorType: "customer",
        requestId
      });
      const response = {
        success: true,
        transactionId: result.transaction.id,
        customerId,
        amount: Number(amount),
        newBalance: Number(result.wallet.balance),
        transactionType: "debit",
        timestamp: result.transaction.created_at,
        message: "Wallet balance used successfully"
      };
      if (idempotencyKey) {
        await storeIdempotencyKey(
          idempotencyKey,
          "wallet_transaction",
          result.transaction.id,
          response,
          200
        );
      }
      return this.success(response);
    } catch (error) {
      if (error.message.includes("Insufficient balance")) {
        return this.error("Insufficient wallet balance", 400);
      }
      if (error.message.includes("Wallet not found")) {
        return this.error("Wallet not found. Please add funds first.", 404);
      }
      throw error;
    }
  }
};
