// src/utils/firebase-client.ts
var admin = null;
var firebaseAvailable = false;
var firebaseLoadAttempted = false;
var firebaseApp = null;
function loadFirebaseAdmin() {
  if (firebaseLoadAttempted) {
    return firebaseAvailable;
  }
  firebaseLoadAttempted = true;
  try {
    admin = eval("require")("firebase-admin");
    firebaseAvailable = true;
    console.log("[Firebase] Module loaded successfully");
    return true;
  } catch (e) {
    console.warn("[Firebase] firebase-admin not available - push notifications disabled");
    firebaseAvailable = false;
    return false;
  }
}
function initializeFirebase() {
  if (!loadFirebaseAdmin()) {
    throw new Error("Firebase not available - push notifications disabled");
  }
  if (firebaseApp) {
    return firebaseApp;
  }
  const serviceAccount = process.env.FIREBASE_SERVICE_ACCOUNT_JSON ? JSON.parse(process.env.FIREBASE_SERVICE_ACCOUNT_JSON) : {
    projectId: process.env.FIREBASE_PROJECT_ID,
    privateKey: process.env.FIREBASE_PRIVATE_KEY?.replace(/\\n/g, "\n"),
    clientEmail: process.env.FIREBASE_CLIENT_EMAIL
  };
  if (!serviceAccount.projectId) {
    console.warn("[Firebase] Missing Firebase configuration - push notifications will be disabled");
    throw new Error("Firebase configuration not found");
  }
  try {
    firebaseApp = admin.initializeApp({
      credential: admin.credential.cert(serviceAccount),
      projectId: serviceAccount.projectId
    });
    console.log("[Firebase] Initialized successfully");
    return firebaseApp;
  } catch (error) {
    console.error("[Firebase] Initialization error:", error);
    throw error;
  }
}
function getFirebaseMessaging() {
  if (!loadFirebaseAdmin()) {
    throw new Error("Firebase not available");
  }
  const app3 = initializeFirebase();
  return admin.messaging(app3);
}
function isFirebaseAvailable() {
  return loadFirebaseAdmin();
}
async function sendPushToDevice(fcmToken, payload) {
  try {
    const messaging = getFirebaseMessaging();
    const message2 = {
      token: fcmToken,
      notification: {
        title: payload.title,
        body: payload.body,
        imageUrl: payload.imageUrl
      },
      data: payload.data,
      android: {
        priority: "high",
        notification: {
          sound: "default",
          clickAction: "FLUTTER_NOTIFICATION_CLICK"
        }
      },
      apns: {
        payload: {
          aps: {
            sound: "default",
            badge: 1
          }
        }
      }
    };
    const response = await messaging.send(message2);
    console.log("[Firebase] Push sent successfully:", response);
    return {
      success: true,
      messageId: response
    };
  } catch (error) {
    console.error("[Firebase] Push notification error:", error);
    if (error.code === "messaging/registration-token-not-registered") {
      return {
        success: false,
        error: "Invalid or expired FCM token"
      };
    }
    return {
      success: false,
      error: error.message
    };
  }
}
async function sendPushToMultipleDevices(fcmTokens, payload) {
  if (fcmTokens.length === 0) {
    return { successCount: 0, failureCount: 0, results: [] };
  }
  try {
    const messaging = getFirebaseMessaging();
    const message2 = {
      tokens: fcmTokens,
      notification: {
        title: payload.title,
        body: payload.body,
        imageUrl: payload.imageUrl
      },
      data: payload.data,
      android: {
        priority: "high",
        notification: {
          sound: "default",
          clickAction: "FLUTTER_NOTIFICATION_CLICK"
        }
      },
      apns: {
        payload: {
          aps: {
            sound: "default",
            badge: 1
          }
        }
      }
    };
    const response = await messaging.sendEachForMulticast(message2);
    const results = response.responses.map((r) => ({
      success: r.success,
      messageId: r.messageId,
      error: r.error?.message
    }));
    console.log(`[Firebase] Multicast: ${response.successCount} success, ${response.failureCount} failed`);
    return {
      successCount: response.successCount,
      failureCount: response.failureCount,
      results
    };
  } catch (error) {
    console.error("[Firebase] Multicast error:", error);
    return {
      successCount: 0,
      failureCount: fcmTokens.length,
      results: fcmTokens.map(() => ({ success: false, error: error.message }))
    };
  }
}
async function sendPushToTopic(topic, payload) {
  try {
    const messaging = getFirebaseMessaging();
    const message2 = {
      topic,
      notification: {
        title: payload.title,
        body: payload.body,
        imageUrl: payload.imageUrl
      },
      data: payload.data,
      android: {
        priority: "high",
        notification: {
          sound: "default"
        }
      },
      apns: {
        payload: {
          aps: {
            sound: "default"
          }
        }
      }
    };
    const response = await messaging.send(message2);
    console.log("[Firebase] Topic push sent:", response);
    return {
      success: true,
      messageId: response
    };
  } catch (error) {
    console.error("[Firebase] Topic push error:", error);
    return {
      success: false,
      error: error.message
    };
  }
}
async function subscribeToTopic(fcmToken, topic) {
  try {
    const messaging = getFirebaseMessaging();
    await messaging.subscribeToTopic(fcmToken, topic);
    console.log(`[Firebase] Subscribed to topic: ${topic}`);
    return true;
  } catch (error) {
    console.error("[Firebase] Subscribe error:", error);
    return false;
  }
}
async function unsubscribeFromTopic(fcmToken, topic) {
  try {
    const messaging = getFirebaseMessaging();
    await messaging.unsubscribeFromTopic(fcmToken, topic);
    console.log(`[Firebase] Unsubscribed from topic: ${topic}`);
    return true;
  } catch (error) {
    console.error("[Firebase] Unsubscribe error:", error);
    return false;
  }
}
