  app3.get("/admin/pets/all", async (c) => {
    try {
      const limit = parseInt(c.req.query("limit") || "100", 10);
      const offset = parseInt(c.req.query("offset") || "0", 10);
      const species = c.req.query("species");
      let queryStr = `
        SELECT 
          p.*,
          c.name as owner_name,
          c.phone as owner_phone
        FROM pets p
        LEFT JOIN customers c ON p.customer_id = c.id
        WHERE 1=1
      `;
      const params = [];
      let paramIndex = 1;
      if (species && species !== "all") {
        queryStr += ` AND p.species = $${paramIndex}`;
        params.push(species);
        paramIndex++;
      }
      queryStr += ` ORDER BY p.created_at DESC LIMIT $${paramIndex} OFFSET $${paramIndex + 1}`;
      params.push(limit, offset);
      const pets = await query(queryStr, params);
      return c.json({
        success: true,
        pets: pets.rows || [],
        total: pets.rows?.length || 0
      });
    } catch (error) {
      console.error("Error fetching pets:", error);
      return c.json({ success: true, pets: [], total: 0 });
    }
  });
  app3.get("/admin/pets/breed-insights", async (c) => {
    try {
      const insights = await query(`
        SELECT 
          breed,
          COUNT(*) as count,
          COALESCE(AVG(age_years + age_months::numeric / 12), 0) as avg_age,
          COUNT(DISTINCT customer_id) as unique_owners
        FROM pets
        WHERE breed IS NOT NULL
        GROUP BY breed
        HAVING COUNT(*) >= 2
        ORDER BY count DESC
        LIMIT 20
      `).catch(() => ({ rows: [] }));
      const insightsWithDetails = await Promise.all(
        insights.rows.map(async (row) => {
          const services = await query(`
            SELECT s.name, COUNT(*) as booking_count
            FROM bookings b
            JOIN services s ON b.service_id = s.id
            JOIN pets p ON b.pet_id = p.id
            WHERE p.breed = $1
            GROUP BY s.name
            ORDER BY booking_count DESC
            LIMIT 5
          `, [row.breed]).catch(() => ({ rows: [] }));
          return {
            breed: row.breed,
            count: parseInt(row.count, 10),
            avgAge: parseFloat(row.avg_age || "0"),
            uniqueOwners: parseInt(row.unique_owners, 10),
            commonServices: services.rows.map((s) => s.name),
            healthRisk: "low",
            // Could be calculated from medical_history
            avgSpend: 0
            // Could be calculated from bookings
          };
        })
      );
      return c.json({
        success: true,
        insights: insightsWithDetails
      });
    } catch (error) {
      console.error("Error fetching breed insights:", error);
      return c.json({ success: true, insights: [] });
    }
  });
