  app3.get("/admin/refunds", async (c) => {
    try {
      const status = c.req.query("status");
      const limit = parseInt(c.req.query("limit") || "50", 10);
      const offset = parseInt(c.req.query("offset") || "0", 10);
      let queryStr = `
        SELECT 
          r.*,
          c.name as customer_name,
          c.phone as customer_phone,
          p.razorpay_payment_id,
          b.service_name
        FROM refunds r
        LEFT JOIN customers c ON r.customer_id = c.id
        LEFT JOIN payments p ON r.payment_id = p.id
        LEFT JOIN bookings b ON r.booking_id = b.id
        WHERE 1=1
      `;
      const params = [];
      let paramIndex = 1;
      if (status && status !== "all") {
        queryStr += ` AND r.refund_status = $${paramIndex}`;
        params.push(status);
        paramIndex++;
      }
      queryStr += ` ORDER BY r.requested_at DESC LIMIT $${paramIndex} OFFSET $${paramIndex + 1}`;
      params.push(limit, offset);
      const refunds = await query(queryStr, params);
      const safeRefunds = (refunds.rows || []).map((r) => ({
        id: String(r.id || ""),
        booking_id: r.booking_id ? String(r.booking_id) : void 0,
        order_id: r.order_id ? String(r.order_id) : void 0,
        customer_name: String(r.customer_name || ""),
        customer_phone: String(r.customer_phone || ""),
        payment_id: String(r.payment_id || ""),
        amount: parseFloat(r.refund_amount || "0"),
        reason: String(r.refund_reason || ""),
        status: String(r.refund_status || "pending"),
        type: r.booking_id ? "booking" : "order",
        created_at: String(r.requested_at || ""),
        processed_at: r.processed_at ? String(r.processed_at) : void 0,
        processed_by: r.processed_by || void 0,
        refund_id: r.razorpay_refund_id || void 0,
        admin_notes: r.admin_comment || void 0
      }));
      return c.json({
        success: true,
        refunds: safeRefunds,
        total: safeRefunds.length
      });
    } catch (error) {
      console.error("Error fetching refunds:", error);
      return c.json({ success: true, refunds: [], total: 0 });
    }
  });
