var ExportTransactionsHandler = class extends BaseHandler {
  async handle(context) {
    try {
      const params = context.event.queryStringParameters || {};
      const format = params.format || "csv";
      const transactions = await query(`
        SELECT 
          t.*,
          v.business_name as vendor_name,
          c.full_name as customer_name
        FROM transactions t
        LEFT JOIN vendors v ON v.id = t.vendor_id
        LEFT JOIN customers c ON c.id = t.customer_id
        ORDER BY t.created_at DESC
      `);
      const rows = transactions.rows || [];
      if (format === "csv") {
        if (rows.length === 0) {
          return this.success({
            success: true,
            exportData: "",
            format: "csv",
            filename: `transactions-${(/* @__PURE__ */ new Date()).toISOString().split("T")[0]}.csv`
          });
        }
        const headers = Object.keys(rows[0]).join(",");
        const csvRows = rows.map(
          (row) => Object.values(row).map((v) => `"${String(v || "").replace(/"/g, '""')}"`).join(",")
        );
        const csv = [headers, ...csvRows].join("\n");
        return this.success({
          success: true,
          exportData: csv,
          format: "csv",
          filename: `transactions-${(/* @__PURE__ */ new Date()).toISOString().split("T")[0]}.csv`
        });
      }
      return this.success({ success: true, transactions: rows });
    } catch (error) {
      console.error("Error exporting transactions:", error);
      return this.success({
        success: true,
        exportData: "",
        format: "csv",
        filename: `transactions-${(/* @__PURE__ */ new Date()).toISOString().split("T")[0]}.csv`
      });
    }
  }
};
