function numberToWords(num) {
  const ones = [
    "",
    "One",
    "Two",
    "Three",
    "Four",
    "Five",
    "Six",
    "Seven",
    "Eight",
    "Nine",
    "Ten",
    "Eleven",
    "Twelve",
    "Thirteen",
    "Fourteen",
    "Fifteen",
    "Sixteen",
    "Seventeen",
    "Eighteen",
    "Nineteen"
  ];
  const tens = ["", "", "Twenty", "Thirty", "Forty", "Fifty", "Sixty", "Seventy", "Eighty", "Ninety"];
  if (num === 0) return "Zero";
  if (num < 0) return "Minus " + numberToWords(-num);
  let words = "";
  if (Math.floor(num / 1e7) > 0) {
    words += numberToWords(Math.floor(num / 1e7)) + " Crore ";
    num %= 1e7;
  }
  if (Math.floor(num / 1e5) > 0) {
    words += numberToWords(Math.floor(num / 1e5)) + " Lakh ";
    num %= 1e5;
  }
  if (Math.floor(num / 1e3) > 0) {
    words += numberToWords(Math.floor(num / 1e3)) + " Thousand ";
    num %= 1e3;
  }
  if (Math.floor(num / 100) > 0) {
    words += numberToWords(Math.floor(num / 100)) + " Hundred ";
    num %= 100;
  }
  if (num > 0) {
    if (words !== "") words += "and ";
    if (num < 20) {
      words += ones[num];
    } else {
      words += tens[Math.floor(num / 10)];
      if (num % 10 > 0) words += " " + ones[num % 10];
    }
  }
  return words.trim();
}

