async function adaptAndHandle(handler2, c) {
  const event = c.env?.event;
  if (!event) {
    return c.json({ error: "Missing event in context" }, 500);
  }
  const handlerContext = {
    event,
    context: {}
  };
  const response = await handler2.handle(handlerContext);
  return c.body(response.body, response.statusCode, {
    "Content-Type": "application/json",
    ...response.headers || {}
  });
}
